using System.Net;
using System.Net.Http.Json;
using DCMS.Application.Features.Examinations;
using DCMS.Application.Features.Finance;
using DCMS.Application.Features.Reception;
using DCMS.Domain.Features.Finance;
using DCMS.Domain.Features.Scheduling;
using DCMS.Domain.Features.Settings;
using DCMS.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Xunit;
namespace DCMS.IntegrationTests;
public sealed class ExaminationBillingApiTests(ReceptionFixture fixture):IClassFixture<ReceptionFixture>
{
 readonly ReceptionApiTests reception=new(fixture);
 static async Task<T> Ok<T>(HttpResponseMessage r){Assert.True(r.IsSuccessStatusCode,await r.Content.ReadAsStringAsync());return (await r.Content.ReadFromJsonAsync<T>())!;}
 static string Fee(Guid v)=>$"/api/finance/visits/{v}/examination-fee";
 static string Bill(Guid v)=>$"/api/finance/visits/{v}";
 async Task<(VisitResult V,HttpClient D,ExaminationServiceOption S)> Prepare(long? price=100000){
  var s=await reception.Prepare();using var a=await reception.Login();var v=await reception.Check(a,s);var d=await reception.Login("dentist.demo");var w=await Ok<ExaminationWorkspace>(await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/start",new StartExamination(v.PatientId,v.VisitVersion,Guid.NewGuid())));
  var content=new ExaminationContent("SYNTHETIC khám tổng quát",new(),new(),new(),[],null,null,Advice:"SYNTHETIC vệ sinh",Disposition:"ProceedToTreatment",Diagnoses:["Chưa phát hiện bất thường"]);
  w=await Ok<ExaminationWorkspace>(await d.PutAsJsonAsync($"/api/visits/{v.VisitId}/examination",new SaveExamination(v.PatientId,w.Visit.VisitVersion,Guid.NewGuid(),content,true)));
  var services=(await d.GetFromJsonAsync<ExaminationServiceOption[]>($"/api/finance/examination-services?branchId={v.BranchId}"))!;var service=Assert.Single(services);service=await Ok<ExaminationServiceOption>(await d.PutAsJsonAsync($"/api/finance/examination-services/{service.Id}",new SaveExaminationService(Guid.NewGuid(),v.BranchId,service.Name,price,service.Version)));return(w.Visit,d,service);
 }
 async Task<ExaminationWorkspace> Close(HttpClient d,VisitResult v,ExaminationFeeChoice? fee=null)=>await Ok<ExaminationWorkspace>(await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/complete",new CompleteExaminationVisit(v.PatientId,v.VisitVersion,Guid.NewGuid(),true,fee)));
 [Fact]public async Task CompletionPostsOneExaminationChargeWithoutTreatmentAndRetryCannotDuplicateIt(){var(v,d,s)=await Prepare();using(d){Assert.Empty((await d.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!.Charges);var cmd=new CompleteExaminationVisit(v.PatientId,v.VisitVersion,Guid.NewGuid(),true,new(s.Id,s.Version,100000));var closed=await Ok<ExaminationWorkspace>(await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/complete",cmd));Assert.Equal("Completed",closed.Visit.Status);await Ok<ExaminationWorkspace>(await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/complete",cmd));var b=(await d.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!;var charge=Assert.Single(b.Charges);Assert.Equal("Examination",charge.SourceKind);Assert.Equal(v.VisitId,charge.SourceId);Assert.Equal(100000,b.RemainingVnd);Assert.Empty(b.Payments);var fee=(await d.GetFromJsonAsync<ExaminationFeeDto>(Fee(v.VisitId)))!;Assert.Equal("Posted",fee.State);Assert.Equal(charge.Id,fee.ChargeId);using var scope=fixture.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<DcmsDbContext>();Assert.False(await db.ClinicalActivities.AnyAsync(x=>x.VisitId==v.VisitId));Assert.Single(await db.Set<FinanceCharge>().Where(x=>x.SourceId==v.VisitId).ToArrayAsync());}}
 [Fact]public async Task MissingPriceDefersFeeAndAddsCompletedConsultationToQueueWithoutFakeZeroDebt(){var(v,d,_)=await Prepare(null);using(d){await Close(d,v);var fee=(await d.GetFromJsonAsync<ExaminationFeeDto>(Fee(v.VisitId)))!;Assert.Equal("Pending",fee.State);Assert.Null(fee.AmountVnd);Assert.Null(fee.ChargeId);Assert.Empty((await d.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!.Charges);var q=(await d.GetFromJsonAsync<QueueBill[]>($"/api/finance/queue?branchId={v.BranchId}"))!;Assert.Equal(1,Assert.Single(q).PendingExaminationFees);}}
 [Theory][InlineData(0L)][InlineData(80000L)]public async Task CashierCanUseConfiguredPriceAfterPendingButCannotOverride(long price){var(v,d,s)=await Prepare(null);using(d)using(var a=await reception.Login()){await Close(d,v);s=await Ok<ExaminationServiceOption>(await d.PutAsJsonAsync($"/api/finance/examination-services/{s.Id}",new SaveExaminationService(Guid.NewGuid(),v.BranchId,s.Name,price,s.Version)));var fee=(await a.GetFromJsonAsync<ExaminationFeeDto>(Fee(v.VisitId)))!;Assert.Equal(HttpStatusCode.Forbidden,(await a.PostAsJsonAsync(Fee(v.VisitId),new SetExaminationFee(v.PatientId,fee.Version,Guid.NewGuid(),new(s.Id,s.Version,price+1,"SYNTHETIC")))).StatusCode);var c=new SetExaminationFee(v.PatientId,fee.Version,Guid.NewGuid(),new(s.Id,s.Version,price));var posted=await Ok<ExaminationFeeDto>(await a.PostAsJsonAsync(Fee(v.VisitId),c));Assert.Equal(price,posted.AmountVnd);await Ok<ExaminationFeeDto>(await a.PostAsJsonAsync(Fee(v.VisitId),c));Assert.Single((await a.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!.Charges);if(price==0){Assert.Equal("Miễn phí theo bảng giá dịch vụ khám",posted.Reason);Assert.Empty((await a.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!.Payments);}}}
 [Theory][InlineData(0L)][InlineData(60000L)]public async Task PhysicianOverrideRequiresReasonAndIsSnapshotted(long amount){var(v,d,s)=await Prepare();using(d){var bad=await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/complete",new CompleteExaminationVisit(v.PatientId,v.VisitVersion,Guid.NewGuid(),true,new(s.Id,s.Version,amount)));Assert.Equal(HttpStatusCode.BadRequest,bad.StatusCode);Assert.Empty((await d.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!.Charges);await Close(d,v,new(s.Id,s.Version,amount,"SYNTHETIC miễn/giảm đã quyết định"));var fee=(await d.GetFromJsonAsync<ExaminationFeeDto>(Fee(v.VisitId)))!;Assert.Equal("Override",fee.PriceSource);Assert.Equal(amount,fee.AmountVnd);}}
 [Theory][InlineData(-1L)][InlineData(1000000000001L)]public async Task InvalidAmountsRollBackClinicalCompletion(long amount){var(v,d,s)=await Prepare();using(d){Assert.Equal(HttpStatusCode.BadRequest,(await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/complete",new CompleteExaminationVisit(v.PatientId,v.VisitVersion,Guid.NewGuid(),true,new(s.Id,s.Version,amount,"SYNTHETIC")))).StatusCode);Assert.Equal("InProgress",(await d.GetFromJsonAsync<ExaminationWorkspace>($"/api/visits/{v.VisitId}/examination"))!.Visit.Status);Assert.Empty((await d.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!.Charges);}}
 [Fact]public async Task ConcurrentCompletionsHaveOneChargeAndStalePriceBlocksBeforeClosing(){var(v,d,s)=await Prepare();using(d)using(var other=await reception.Login("dentist.demo")){var changed=await Ok<ExaminationServiceOption>(await d.PutAsJsonAsync($"/api/finance/examination-services/{s.Id}",new SaveExaminationService(Guid.NewGuid(),v.BranchId,s.Name,120000,s.Version)));Assert.Equal(HttpStatusCode.Conflict,(await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/complete",new CompleteExaminationVisit(v.PatientId,v.VisitVersion,Guid.NewGuid(),true,new(s.Id,s.Version,100000)))).StatusCode);var cmd=new CompleteExaminationVisit(v.PatientId,v.VisitVersion,Guid.NewGuid(),true,new(changed.Id,changed.Version,120000));var results=await Task.WhenAll(d.PostAsJsonAsync($"/api/visits/{v.VisitId}/complete",cmd),other.PostAsJsonAsync($"/api/visits/{v.VisitId}/complete",cmd with{RequestKey=Guid.NewGuid()}));Assert.Equal(1,results.Count(x=>x.IsSuccessStatusCode));Assert.Single((await d.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!.Charges);}}
 [Fact]public async Task FeesRemainUnchangedByCatalogOrClinicalAmendmentAndPostedCannotBeEdited(){var(v,d,s)=await Prepare();using(d){var closed=await Close(d,v);await Ok<ExaminationServiceOption>(await d.PutAsJsonAsync($"/api/finance/examination-services/{s.Id}",new SaveExaminationService(Guid.NewGuid(),v.BranchId,"SYNTHETIC khám mới",200000,s.Version)));var fee=(await d.GetFromJsonAsync<ExaminationFeeDto>(Fee(v.VisitId)))!;await Ok<ExaminationWorkspace>(await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/examination/amend",new AmendExamination(v.PatientId,closed.Visit.VisitVersion,Guid.NewGuid(),closed.Examination!.Content with{Advice="SYNTHETIC dặn dò bổ sung"},"SYNTHETIC đính chính")));var same=(await d.GetFromJsonAsync<ExaminationFeeDto>(Fee(v.VisitId)))!;Assert.Equal(100000,same.AmountVnd);Assert.Equal(s.Name,same.ServiceName);Assert.Equal(HttpStatusCode.Conflict,(await d.PostAsJsonAsync(Fee(v.VisitId),new SetExaminationFee(v.PatientId,same.Version,Guid.NewGuid(),new(s.Id,s.Version+1,200000)))).StatusCode);}}
 [Fact]public async Task PartialCashThenTransferMustBeConfirmedAndCloseDoesNotCollectAutomatically(){var(v,d,s)=await Prepare();using(d)using(var a=await reception.Login()){await Close(d,v);var b=(await a.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!;var charge=Assert.Single(b.Charges);var cash=await Ok<PaymentDto>(await a.PostAsJsonAsync(Bill(v.VisitId)+"/payments",new CollectPayment(v.PatientId,b.AccountVersion,Guid.NewGuid(),"Cash","SYNTHETIC người nộp",[new(charge.Id,30000)])));Assert.Equal("Posted",cash.State);b=(await a.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!;Assert.Equal(70000,b.RemainingVnd);var transfer=await Ok<PaymentDto>(await a.PostAsJsonAsync(Bill(v.VisitId)+"/payments",new CollectPayment(v.PatientId,b.AccountVersion,Guid.NewGuid(),"Transfer","SYNTHETIC người nộp",[new(charge.Id,70000)])));b=(await a.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!;Assert.Equal(30000,b.PaidVnd);await Ok<PaymentDto>(await a.PostAsJsonAsync($"/api/finance/payments/{transfer.Id}/confirm",new ConfirmPayment(transfer.Version,b.AccountVersion,Guid.NewGuid(),"EXAM-"+Guid.NewGuid(),"SYNTHETIC đối chiếu")));Assert.Equal(0,(await a.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!.RemainingVnd);}}
 [Fact]public async Task ReadDoesNotCreateFeeAndLegacyRequiresExplicitReason(){var(v,d,s)=await Prepare();using(d){await d.GetFromJsonAsync<ExaminationFeeDto>(Fee(v.VisitId));using(var scope=fixture.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<DcmsDbContext>();Assert.False(await db.Set<ExaminationFee>().AnyAsync(x=>x.VisitId==v.VisitId));var row=await db.Visits.SingleAsync(x=>x.Id==v.VisitId);row.Status="Completed";var a=await db.Appointments.SingleAsync(x=>x.Id==v.AppointmentId);a.Status="Completed";await db.SaveChangesAsync();}var fee=(await d.GetFromJsonAsync<ExaminationFeeDto>(Fee(v.VisitId)))!;Assert.True(fee.Legacy);Assert.Equal(HttpStatusCode.BadRequest,(await d.PostAsJsonAsync(Fee(v.VisitId),new SetExaminationFee(v.PatientId,0,Guid.NewGuid(),new(s.Id,s.Version,100000)))).StatusCode);await Ok<ExaminationFeeDto>(await d.PostAsJsonAsync(Fee(v.VisitId),new SetExaminationFee(v.PatientId,0,Guid.NewGuid(),new(s.Id,s.Version,100000,"SYNTHETIC đối chiếu lượt cũ"))));}}
 [Fact]public async Task BranchRevocationAndWrongPatientCannotPostFee(){var(v,d,s)=await Prepare(null);using(d){await Close(d,v);Assert.Equal(HttpStatusCode.NotFound,(await d.PostAsJsonAsync(Fee(v.VisitId),new SetExaminationFee(v.PatientId+999,1,Guid.NewGuid(),new(s.Id,s.Version,100000,"SYNTHETIC")))).StatusCode);using var scope=fixture.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<DcmsDbContext>();var actor=await db.Users.Where(x=>x.UserName=="dentist.demo").Select(x=>x.Id).SingleAsync();var g=new AccessGroup{Code="EX-"+Guid.NewGuid().ToString("N"),Name="SYNTHETIC",BaseRole="Dentist"};g.NormalizedCode=g.Code;g.NormalizedName=g.Code;g.Grants.Add(new(){GroupId=g.Id,Permission="finance.read"});g.Grants.Add(new(){GroupId=g.Id,Permission="finance.quotes.manage"});db.Add(g);db.Add(new StaffAccessAssignment{AccountId=actor,GroupId=g.Id,BranchIds=[]});await db.SaveChangesAsync();try{Assert.Equal(HttpStatusCode.Forbidden,(await d.PostAsJsonAsync(Fee(v.VisitId),new SetExaminationFee(v.PatientId,1,Guid.NewGuid(),new(s.Id,s.Version,100000,"SYNTHETIC")))).StatusCode);}finally{await db.Set<StaffAccessAssignment>().ExecuteDeleteAsync();}}}

 [Fact]public async Task ConfiguredFreeCompletesWithoutDebtOrReceipt(){var(v,d,_)=await Prepare(0);using(d){await Close(d,v);var b=(await d.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!;Assert.Equal(0,Assert.Single(b.Charges).AmountVnd);Assert.Equal(0,b.RemainingVnd);Assert.Empty(b.Payments);Assert.Equal("Catalog",(await d.GetFromJsonAsync<ExaminationFeeDto>(Fee(v.VisitId)))!.PriceSource);}}
 [Fact]public async Task UnreviewedCompletionCannotPostFee(){var(v,d,_)=await Prepare();using(d){Assert.Equal(HttpStatusCode.Conflict,(await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/complete",new CompleteExaminationVisit(v.PatientId,v.VisitVersion,Guid.NewGuid(),false))).StatusCode);Assert.Empty((await d.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!.Charges);}}
 [Fact]public async Task CompletedExaminationAndPerformedInvestigationShareOneBill(){var(v,d,_)=await Prepare();using(d){
 var page=await Ok<InvestigationPage>(await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/investigations",new CreateInvestigation(v.PatientId,v.VisitVersion,Guid.NewGuid(),"Lab","SYNTHETIC CBC",null,"SYNTHETIC",false,ExpectedExaminationVersion:1,AmendmentReason:"SYNTHETIC bổ sung")));var order=Assert.Single(page.Items);
 var service=await Ok<InvestigationServiceDto>(await d.PostAsJsonAsync("/api/finance/services",new SaveInvestigationService(Guid.NewGuid(),v.BranchId,"SYNTHETIC CBC","Lab","Lần",200000)));
 var path=$"/api/visits/{v.VisitId}/investigations/{order.Id}/billing";
 var quote=await Ok<InvestigationBillingDto>(await d.PostAsJsonAsync(path+"/quote",new QuoteInvestigation(v.PatientId,page.VisitVersion,order.Version,Guid.NewGuid(),"Clinic",service.Id,service.Version)));
 var performed=await Ok<InvestigationBillingDto>(await d.PostAsJsonAsync(path+"/perform",new PerformInvestigation(v.PatientId,quote.VisitVersion,quote.OrderVersion,Guid.NewGuid())));
 var result=await Ok<InvestigationPage>(await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/investigations/{order.Id}/result",new ReceiveInvestigationResult(v.PatientId,performed.VisitVersion,performed.OrderVersion,Guid.NewGuid(),"SYNTHETIC kết quả")));
 var reviewed=await Ok<InvestigationPage>(await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/investigations/{order.Id}/review",new ReviewInvestigation(v.PatientId,result.VisitVersion,Assert.Single(result.Items).Version,Guid.NewGuid())));
 var current=(await d.GetFromJsonAsync<ExaminationWorkspace>($"/api/visits/{v.VisitId}/examination"))!;
 var amended=await Ok<ExaminationWorkspace>(await d.PostAsJsonAsync($"/api/visits/{v.VisitId}/examination/amend",new AmendExamination(v.PatientId,reviewed.VisitVersion,Guid.NewGuid(),current.Examination!.Content,"SYNTHETIC cập nhật kết quả")));
 await Close(d,amended.Visit);var bill=(await d.GetFromJsonAsync<BillDto>(Bill(v.VisitId)))!;Assert.Equal(2,bill.Charges.Count);Assert.Equal(300000,bill.TotalVnd);Assert.Equal(300000,bill.RemainingVnd);Assert.Empty(bill.Payments);
 }}
}
